my $savetoX3='';
while (my $line=<FILE>){
  chomp $line; 
  my @parts=split(' ',$line,2); 
  if ( (!$saveX1) && $parts[0] eq 'X1') { $savetoX1=$parts[1]; $saveX1=1; } 
  elsif ($parts[0] eq 'X2' ||($parts[0] eq 'BEGIN' && $parts[2] eq 'TAG' ) ){ 
       #print $savetoX1."\n" if ($savetoX1) ; 
       $savetoX1=''; 
       $saveX1=0; 
       } 
  elsif ($saveX1) { $savetoX1.=' '.$line; } 


  if ( (!$saveX2) && $parts[0] eq 'X2') { $savetoX2=$parts[1]; $saveX2=1; } 
  elsif ($parts[0] eq 'X3' ||($parts[0] eq 'BEGIN' && $parts[2] eq 'TAG' ) ){ 
       #print $savetoX2."\n" if ($savetoX2) ; 
       $savetoX2=''; 
       $saveX2=0; 
       } 
  elsif ($saveX2) { $savetoX2.=' '.$line; } 


  if ( (!$saveX3) && $parts[0] eq 'X3') { $savetoX3=$parts[1]; $saveX3=1; } 
  elsif ($parts[0] eq 'BEGIN' && $parts[2] eq 'TAG' ){ 
		#print $savetoX3."\n" if ($savetoX3) ; 
		$savetoX3=''; 
		$saveX3=0; 
       } 
  elsif ($saveX3) { $savetoX3.=' '.$line; } 




  }
print "X1: ".$savetoX1."\n" if ($savetoX1) ; 
print "X2: ".$savetoX2."\n" if ($savetoX2) ; 
print "X3: ".$savetoX3."\n" if ($savetoX3) ; 

